npm install @sentry/node 2>&1 | tail -3
cat > src/instrument.js <<'EOF'
import * as Sentry from '@sentry/node';

// GlitchTip speaks the Sentry protocol; the DSN comes from GLITCHTIP_DSN.
// Without a DSN the SDK is a no-op, so local dev works unchanged.
Sentry.init({
  dsn: process.env.GLITCHTIP_DSN,
  environment: process.env.NODE_ENV || 'development',
});

export { Sentry };
EOF
cat > src/server.js <<'EOF'
import { Sentry } from './instrument.js'; // must be first
import express from 'express';
import { listsForHousehold } from './lists.js';

const app = express();
app.use(express.json());

app.get('/households/:id/lists', async (req, res) => {
  res.json(await listsForHousehold(req.params.id));
});

// After all routes. Express 5 forwards async rejections here.
Sentry.setupExpressErrorHandler(app);

app.listen(process.env.PORT || 3000);
EOF
